const STORAGE_KEY = 'square_feed_refresh_requested_at';

export function requestSquareFeedRefresh() {
	try {
		uni.setStorageSync(STORAGE_KEY, Date.now());
	} catch (error) {}
}

export function consumeSquareFeedRefresh() {
	try {
		const requestedAt = Number(uni.getStorageSync(STORAGE_KEY) || 0);
		if (!requestedAt) return false;
		uni.removeStorageSync(STORAGE_KEY);
		return true;
	} catch (error) {
		return false;
	}
}
